import { beforeEach, describe, expect, it } from 'vitest';
import { supabase } from '@/lib/supabase';
import { appendChangeLog } from './repo';
import { mockSupabase } from '@/lib/supabase.mock';

describe('appendChangeLog', () => {
  beforeEach(() => {
    mockSupabase();
  });

  it('should not include id in payload', async () => {
    const spy = vi.spyOn(supabase, 'from').mockResolvedValueOnce({
      data: [],
      error: null,
    });

    await appendChangeLog({ message: 'Test log' });

    expect(spy).toHaveBeenCalledWith('changelog', {
      insert: [{ message: 'Test log' }],
    });
  });

  it('should propagate errors', async () => {
    const spy = vi.spyOn(supabase, 'from').mockRejectedValueOnce(new Error('Database error'));

    await expect(appendChangeLog({ message: 'Test log' })).rejects.toThrow('Database error');
  });
});

